-- ef = la entrada (m/x/y) solo vale para esa facción; la otra ve la zona (zm) y el aviso "entrada aún no confirmada"
do
  local f = CreateFrame and CreateFrame("Frame")
  local function quitar()
    local fac = UnitFactionGroup and UnitFactionGroup("player")
    if not fac then return end
    for _, m in ipairs(WowFMazmorras) do if m.ef and m.ef ~= fac then m.m, m.x, m.y = nil, nil, nil end end
  end
  quitar()
  if f then f:RegisterEvent("PLAYER_LOGIN"); f:SetScript("OnEvent", quitar) end
end
